import inspect
import functools

def get_globals_logic(call):
    unwrapped = call
    while isinstance(unwrapped, functools.partial):
        unwrapped = unwrapped.func
    unwrapped = inspect.unwrap(unwrapped)
    if not hasattr(unwrapped, "__globals__"):
        unwrapped = getattr(unwrapped, "__call__", unwrapped)
    return getattr(unwrapped, "__globals__", {})

def my_func():
    pass

class MyCallable:
    def __call__(self):
        pass

my_callable = MyCallable()
partial_func = functools.partial(my_func)
partial_callable = functools.partial(my_callable)

print(f"Func globals: {get_globals_logic(my_func) is my_func.__globals__}")
print(f"Partial func globals: {get_globals_logic(partial_func) is my_func.__globals__}")
print(f"Callable globals: {get_globals_logic(my_callable) is my_callable.__call__.__globals__}")
print(f"Partial callable globals: {get_globals_logic(partial_callable) is my_callable.__call__.__globals__}")

